let storageWorks=true;
const read = (key,fallback) => {try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{storageWorks=false}};
const allowedQuestIds=['coding-python','coding-cpp','coding-csharp','coding-windows','office-excel','office-word','office-ppt','typing-run',...SATMath.questions.map(question=>question.id)];
const initial=read('levelup-progress',{});
const state={completed:Array.isArray(initial.completed)?[...new Set(SATMath.migrateCompleted(initial.completed).filter(x=>allowedQuestIds.includes(x)))]:[],days:Array.isArray(initial.days)?[...new Set(initial.days.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))]:[]};
if(Array.isArray(initial.completed)&&initial.completed.some(id=>['math-linear','math-quadratic'].includes(id)))write('levelup-progress',state);
function detectLanguage(){const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;if(['Asia/Tashkent','Asia/Samarkand'].includes(zone))return 'uz';const languages=navigator.languages||[navigator.language];for(const l of languages){if(l?.startsWith('uz'))return 'uz';if(l?.startsWith('ru'))return 'ru';if(l?.startsWith('en'))return 'en'}return 'en'}
let lang=typeof location!=='undefined'?new URLSearchParams(location.search).get('lang'):null;lang=lang||read('levelup-language',null);if(!copy[lang])lang=detectLanguage();
const t=k=>copy[lang][k]||copy.en[k]||k;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function localDay(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function save(){write('levelup-progress',state)}
function award(id){const fresh=!state.completed.includes(id);if(fresh)state.completed.push(id);const day=localDay();if(!state.days.includes(day))state.days.push(day);save();renderStats();return fresh}
function unlocked(world){return (typeof window!=='undefined'&&window.levelupCredits?.isDeveloper())||state.completed.some(id=>id.startsWith(world+'-'))}

function renderStats(){
  const xp=state.completed.length*50,level=Math.floor(xp/100)+1;
  $('#main-level').textContent=`${t('level').toUpperCase()} ${String(level).padStart(2,'0')}`;
  $('#total-xp').textContent=`${xp} XP`;
  let streak=0,d=new Date();
  if(!state.days.includes(localDay(d)))d.setDate(d.getDate()-1);
  while(state.days.includes(localDay(d))){streak++;d.setDate(d.getDate()-1)}
  $('#streak').textContent=streak;
}
const worlds=[
  {id:'coding',desc:'codingDesc',tags:['Python','C++','C#','Windows'],reward:'robot'},
  {id:'office',desc:'officeDesc',tags:['Excel','Word','PowerPoint'],reward:'memory'},
  {id:'math',desc:'mathDesc',tags:['SAT','mathPractice','Desmos'],reward:'block'},
  {id:'typing',desc:'typingDesc',tags:['speed','accuracy','rhythm'],reward:'train'}
];
function render(){
  document.documentElement.lang=lang;document.title='ZEHN-EDU — '+t('dashboard');
  $$('[data-i]').forEach(e=>e.innerHTML=t(e.dataset.i));$('#language').value=lang;
  $('#close-modal').ariaLabel=t('close');
  $('.skip').textContent={en:'Skip to content',uz:'Asosiy qismga o‘tish',ru:'Перейти к содержимому'}[lang];
  $$('.index-link,.round-link').forEach(e=>e.ariaLabel=t('explore'));
  $('#world-grid').innerHTML=worlds.map((w,i)=>`<article class="subject subject-${w.id}"><button class="subject-button" data-world="${w.id}" aria-labelledby="subject-${w.id}-title" aria-describedby="subject-${w.id}-desc"><div class="subject-body"><div class="subject-top"><span class="subject-number" aria-hidden="true">0${i+1}</span><span class="subject-tags">${w.tags.map(tag=>esc(copy.en[tag]?t(tag):tag)).join(' / ')}</span></div><div class="subject-main"><div class="subject-copy"><h3 id="subject-${w.id}-title">${t(w.id)}</h3><p id="subject-${w.id}-desc">${t(w.desc)}</p></div></div></div><div class="subject-visual world-art art-${w.id}" aria-hidden="true"></div><div class="subject-footer"><div class="subject-reward"><span>${t(w.id==='typing'?'subjectTypingGame':'subjectGame')}</span><strong>${t(w.reward)}</strong></div><div class="subject-action"><span>${t(w.id==='typing'?'subjectTypeStart':'subjectStart')}</span><span class="subject-arrow" aria-hidden="true">↗</span></div></div></button></article>`).join('');
  renderStats();
  if(typeof window!=='undefined')window.levelupCredits?.render();
}
let cleanup=()=>{},returnFocus=null;
const modal=$('#modal');
function show(kicker,html){cleanup();cleanup=()=>{};$('#modal-kicker').textContent=t(kicker);$('#modal-content').innerHTML=html;if(!modal.open){returnFocus=document.activeElement;modal.showModal()}modal.scrollTo({top:0,behavior:'instant'})}
function close(){cleanup();cleanup=()=>{};modal.close();returnFocus?.focus()}
$('#close-modal').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close()});modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close()}});
$('#language').onchange=e=>{lang=e.target.value;write('levelup-language',lang);if(modal.open)close();render()};
document.addEventListener('click',e=>{const world=e.target.closest('button[data-world]');if(world){openWorld(world.dataset.world);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='typing')openTyping();if(action==='quests')openQuests();if(action==='achievements')openAchievements();if(action==='arena')openArena()});
