function openMemory(){if(!gameGate('office'))return;show('memory',`<h2 id="modal-title">${t('memory')}</h2><p>${t('memoryHelp')}</p><div class="memory"></div><div id="feedback" class="feedback" role="status"></div><div class="game-buttons"><button id="restart-memory" class="primary">${t('restart')}</button><button class="mode-button" data-world="office">${t('back')}</button></div>`);const pairs=[['Ctrl + C','copy'],['Ctrl + V','paste'],['Ctrl + S','save'],['Ctrl + Z','undo']],cards=shuffle(pairs.flatMap(([key,label],id)=>[{id,text:key},{id,text:t(label)}]));let selected=[],matched=new Set(),busy=false,timer;function draw(){$('.memory').innerHTML=cards.map((c,i)=>`<button data-card="${i}" class="${matched.has(c.id)?'matched':selected.includes(i)?'revealed':''}" ${matched.has(c.id)?'disabled':''} aria-label="${matched.has(c.id)||selected.includes(i)?esc(c.text):String(i+1)}">${matched.has(c.id)||selected.includes(i)?esc(c.text):'?'}</button>`).join('');$$('[data-card]').forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)))}function flip(i){if(busy||selected.includes(i)||matched.has(cards[i].id))return;selected.push(i);draw();if(selected.length===2){busy=true;timer=setTimeout(()=>{if(cards[selected[0]].id===cards[selected[1]].id)matched.add(cards[i].id);selected=[];busy=false;draw();if(matched.size===4){$('#feedback').className='feedback success';$('#feedback').textContent=t('memoryWin')}},750)}}cleanup=()=>clearTimeout(timer);$('#restart-memory').onclick=openMemory;draw()}
